queries.snippet:
void leaky() {
  int* p = new int(42);
  // forgot to delete p — leak
}

void mismatched_delete() {
  int* arr = new int[10];
  delete arr;  // should be delete[]
}

void double_free() {
  int* p = new int(7);
  delete p;
  delete p;  // double free
}

int* dangling() {
  int x = 5;
  return &x;  // returning address of local — dangling
}

void pointer_arith(int* buf, std::size_t n) {
  for (int* p = buf; p < buf + n; ++p) {
    *p = 0;
  }
}

void weak_use(std::weak_ptr<int> w) {
  *w = 5;  // direct deref of weak_ptr — must lock first
}

